class Solution:
    def smallestString(self, s: str) -> str:
        n = len(s)
        i = 0
        # Find the first non 'a' character
        while i < n and s[i] == 'a':
            i += 1

        # If all characters are 'a', replace the last one with 'z'
        if i == n:
            return s[:-1] + 'z'

        # Find the end of the consecutive non 'a' characters starting from i
        j = i
        while j < n and s[j] != 'a':
            j += 1

        # Convert each character in the substring s[i..j-1] to previous character
        res = list(s)
        for k in range(i, j):
            res[k] = chr(ord(res[k]) - 1)

        return ''.join(res)
