class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        count = Counter(nums)
        max_len = 0
        for x in count:
            current = x
            m = 0
            while True:
                if current == 1:
                    m_total = (count[1] - 1) // 2
                    m += m_total
                    break
                sqrt_val = math.isqrt(current)
                if sqrt_val * sqrt_val != current:
                    break
                if count.get(sqrt_val, 0) >= 2:
                    m += 1
                    current = sqrt_val
                else:
                    break
            candidate_length = 2 * m + 1
            if candidate_length > max_len:
                max_len = candidate_length
        return max_len if max_len > 0 else 1

