        for n in range(max_comb + 1):
            comb[n][0] = 1
            for k_comb in range(1, n + 1):
                comb[n][k_comb] = (comb[n-1][k_comb-1] + comb[n-1][k_comb]) % MOD

        # Compute dp for steps required to reduce each count to 1
        max_c = L
        dp = [0] * (max_c + 1)
        for c in range(1, max_c + 1):
            if c == 1:
                dp[c] = 0
            else:
                bits = bin(c)[2:]
                cnt = bits.count('1')
                dp[c] = 1 + dp[cnt]

        total = 0

        # Helper function to count numbers with exactly len(s) bits, less than s, with c bits set
        def count_less(s_str, c_target):
            L = len(s_str)
            bits = [int(ch) for ch in s_str]
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, count, tight):
                if pos == L:
                    return 1 if count == c_target else 0
                limit = bits[pos] if tight else 1
                total = 0
                if pos == 0:
                    # Must choose 1
                    if 1 > limit:
                        return 0
                    new_tight = tight and (1 == limit)
                    new_count = count + 1
                    if new_count > c_target:
                        return 0
                    total += dp(pos + 1, new_count, new_tight)
                else:
                    for digit in [0, 1]:
                        if digit > limit:
                            continue
                        new_tight = tight and (digit == limit)
                        new_count = count + (digit == 1)
                        if new_count > c_target:
                            continue
                        total += dp(pos + 1, new_count, new_tight)
                return total % MOD

            # Calculate count_less_equal
            count_less_equal = dp(0, 0, True)
            # Check if s has exactly c_target bits
            actual_bits = bin(int(s_str, 2)).count('1')
            if actual_bits == c_target:
                count_less_equal = (count_less_equal - 1) % MOD
            return count_less_equal

        for c in range(1, max_c + 1):
            if 1 + dp[c] <= k:
                # Compute sum_short
                sum_short = 0
                for l in range(1, L):
                    if c <= l:
