            for m_val in range(1, l + 1):
                comb[l][m_val] = comb[l-1][m_val-1] + comb[l-1][m_val]
                if comb[l][m_val] >= MOD:
                    comb[l][m_val] -= MOD

        # Helper function to count numbers with same length as s and exactly m set bits
        def count_same_length(s, m):
