                            continue
                        new_tight = tight and (bit == limit)
                        new_count = count + (bit == 1)
                        if new_count > m:
                            continue
                        total += dp(pos + 1, new_count, new_tight)
                        total %= MOD
                return total % MOD

            return dp(0, 0, True)

        total = 0
        for m in range(1, len_s + 1):
            if dp_steps[m] <= k - 1:
                part1 = 0
                for l in range(1, len_s):
                    if m - 1 >= 0 and l - 1 >= m - 1:
