            memo_steps[m] = res
            return res

        # Determine M: m with steps(m) <= k-1
        M = []
        for m in range(1, max_m+1):
            # m must be at least 1, as set bits
            if steps(m) <= k-1:
                M.append(m)

        # Now, for each m in M, compute the count of numbers <n with exactly m bits
        total = 0
        for m in M:
            # part1: sum for all lengths < len_s
            part1 = 0
            for L in range(1, len_s):
                # for this L bits, the number of numbers with exactly m bits set is C(L-1, m-1)
                if m > L:
                    continue
                # C(L-1, m-1)
                if (L-1) >= (m-1) and (m-1) >=0:
                    part1 += comb[L-1][m-1]
                    part1 %= MOD
