                # with memoization
                from functools import lru_cache
                @lru_cache(maxsize=None)
                def dp(pos, cnt, tight):
                    if pos == len_s:
                        return 1 if cnt == m else 0
                    res = 0
                    if pos == 0:
                        # first bit must be 1
                        bit = 1
                        new_tight = tight and (bit == bits[pos])
                        new_cnt = cnt + (bit ==1)
                        if new_cnt > m:
