                            if new_cnt > m:
                                continue
                            res += dp(pos+1, new_cnt, new_tight)
                        return res
                return dp(0, 0, True)
            part2 = count_len_s(m, bits, len_s)
            # Add part1 and part2 to total
            total = (total + part1 + part2) % MOD
