    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        max_c = len(s)

        # Precompute steps_count_of_bits for all c from 1 to max_c
        memo_steps = {}

        def compute_steps(c):
            if c == 1:
                return 0
            if c in memo_steps:
                return memo_steps[c]
            bits = bin(c).count('1')
            res = 1 + compute_steps(bits)
            memo_steps[c] = res
            return res

        steps_count_of_bits = [0] * (max_c + 1)
        for c in range(1, max_c + 1):
            steps_count_of_bits[c] = compute_steps(c)

        # Now, compute the count of numbers less than n with exactly m set bits
        bits_list = [int(c) for c in s]
        n = len(bits_list)

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos, tight, count):
            if pos == n:
                return {count: 1}
            res = {}
            max_bit = bits_list[pos] if tight else 1
            for bit in [0, 1]:
                if bit > max_bit:
                    continue
                new_tight = tight and (bit == max_bit)
                new_count = count + (bit == 1)
                sub = dp(pos + 1, new_tight, new_count)
                for k_sub, v_sub in sub.items():
                    if k_sub in res:
                        res[k_sub] += v_sub
                    else:
                        res[k_sub] = v_sub
            return res

        total = dp(0, True, 0)

        # Subtract the case where the number is exactly s
        s_set_bits = sum(bits_list)
        if s_set_bits in total:
            total[s_set_bits] -= 1

        # Remove zero case
        if 0 in total:
            total[0] = 0

        ans = 0
        for m in total:
            if steps_count_of_bits[m] <= k - 1:
                ans = (ans + total[m]) % MOD

        return ans

