class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        # Initialize previous_dp for the first pair (k=0)
        previous_dp = [[float('inf')] * 3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    previous_dp[a][b] = cost[0][a] + cost[n-1][b]

        # Iterate through the remaining pairs
        for k in range(1, m):
            current_dp = [[float('inf')] * 3 for _ in range(3)]
            for a_curr in range(3):
                for b_curr in range(3):
                    if a_curr == b_curr:
                        continue
                    # Find the minimum value from previous_dp where a_prev != a_curr and b_prev != b_curr
                    min_prev = float('inf')
                    for a_prev in range(3):
                        for b_prev in range(3):
                            if a_prev != a_curr and b_prev != b_curr:
                                if previous_dp[a_prev][b_prev] < min_prev:
