class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                set_i = set(properties[i])
                set_j = set(properties[j])
                common = set_i & set_j
                if len(common) >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        visited = [False] * n
        count = 0

        for i in range(n):
            if not visited[i]:
                count += 1
                queue = deque()
                queue.append(i)
                visited[i] = True
                while queue:
                    node = queue.popleft()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return count
